import { Component, inject, signal, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../../services/auth.service';
import { UserService } from '../../../services/user.service';
import { SolicitudService, Municipio } from '../../../shared/services/solicitud.service';
import { roleLabel } from '../../../models/user.model';
import { extractErrorMessage } from '../../../shared/utils/error-utils';

@Component({
  selector: 'app-inversores-perfil',
  standalone: true,
  imports: [ReactiveFormsModule],
  templateUrl: './perfil.component.html',
})
export class PerfilComponent implements OnInit {
  private readonly fb = inject(FormBuilder);
  private readonly authService = inject(AuthService);
  private readonly userService = inject(UserService);
  private readonly solicitudService = inject(SolicitudService);
  private readonly router = inject(Router);
  protected readonly user = this.authService.currentUser;
  protected readonly submitting = signal(false);
  protected readonly errorMessage = signal('');
  protected readonly successMessage = signal('');
  protected readonly showPasswordSection = signal(false);
  protected readonly municipios = signal<Municipio[]>([]);
  protected form!: FormGroup;
  protected readonly roleLabel = roleLabel;

  ngOnInit(): void {
    this.initForm();
    this.loadMunicipios();
  }

  private loadMunicipios(): void {
    this.solicitudService.getMunicipios().subscribe({
      next: (data) => this.municipios.set(data),
      error: () => this.municipios.set([]),
    });
  }

  private initForm(): void {
    const currentUser = this.user();
    this.form = this.fb.group({
      name: [currentUser?.name || '', [Validators.required, Validators.maxLength(255)]],
      email: [currentUser?.email || '', [Validators.required, Validators.email, Validators.maxLength(255)]],
      municipio: [currentUser?.municipio || ''],
      changePasswordToggle: [false],
      current_password: [''],
      password: [''],
      password_confirmation: [''],
    });
  }

  protected togglePasswordSection(event: Event): void {
    const checked = (event.target as HTMLInputElement).checked;
    this.showPasswordSection.set(checked);
    const currentPass = this.form.get('current_password');
    const pass = this.form.get('password');
    const confirmPass = this.form.get('password_confirmation');

    if (checked) {
      currentPass?.setValidators([Validators.required]);
      pass?.setValidators([Validators.required, Validators.minLength(8)]);
      confirmPass?.setValidators([Validators.required]);
    } else {
      this.resetPasswordValidators();
    }

    currentPass?.updateValueAndValidity();
    pass?.updateValueAndValidity();
    confirmPass?.updateValueAndValidity();
  }

  private resetPasswordValidators(): void {
    const currentPass = this.form.get('current_password');
    const pass = this.form.get('password');
    const confirmPass = this.form.get('password_confirmation');

    currentPass?.clearValidators();
    pass?.clearValidators();
    confirmPass?.clearValidators();

    currentPass?.setValue('');
    pass?.setValue('');
    confirmPass?.setValue('');

    currentPass?.updateValueAndValidity();
    pass?.updateValueAndValidity();
    confirmPass?.updateValueAndValidity();
  }

  protected onSubmit(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    if (
      this.showPasswordSection() &&
      this.form.value.password !== this.form.value.password_confirmation
    ) {
      this.errorMessage.set('La nueva contraseña y su confirmación no coinciden.');
      return;
    }

    this.submitting.set(true);
    this.errorMessage.set('');
    this.successMessage.set('');

    const payload = {
      name: this.form.value.name,
      email: this.form.value.email,
      municipio: this.form.value.municipio || null,
      ...(this.showPasswordSection()
        ? {
            current_password: this.form.value.current_password,
            password: this.form.value.password,
            password_confirmation: this.form.value.password_confirmation,
          }
        : {}),
    };

    this.userService.updateProfile(payload).subscribe({
      next: (res) => {
        this.submitting.set(false);
        if (res.requiresVerification) {
          this.router.navigate(['/login']);
          return;
        }

        this.successMessage.set('Perfil actualizado exitosamente.');
        if (this.showPasswordSection()) {
          this.form.get('changePasswordToggle')?.setValue(false);
          this.showPasswordSection.set(false);
          this.resetPasswordValidators();
        }
      },
      error: (err) => {
        this.submitting.set(false);
        this.errorMessage.set(extractErrorMessage(err));
      },
    });
  }
}
